1	// Base CSV parser interface and utilities for credit card and bank transaction parsing
2	
3	import type { ParsedTransaction, CSVParseResult } from '$lib/models/Transaction';
4	
5	/**
6	 * Base interface for all CSV parsers
7	 */
8	export interface ICSVParser {
9		/**
10		 * Parse a CSV string and return transactions
11		 * @param csvContent The raw CSV file content as a string
12		 * @returns CSVParseResult with parsed transactions and any errors
13		 */
14		parse(csvContent: string): CSVParseResult;
15	
16		/**
17		 * Validate if the CSV format matches this parser's expected format
18		 * @param csvContent The raw CSV file content as a string
19		 * @returns true if the format matches, false otherwise
20		 */
21		validateFormat(csvContent: string): boolean;
22	}
23	
24	/**
25	 * Resolved column layout for a parser.
26	 *
27	 * The Template Method only needs to know where the data rows start; each parser
28	 * extends this with whatever column indices its `parseRow` hook consumes.
29	 */
30	export interface CSVLayout {
31		/** First row index (0-based) that holds transaction data, not headers. */
32		dataStartIndex: number;
33	}
34	
35	/**
36	 * Base CSV parser with a shared `parse()` Template Method and common utilities.
37	 *
38	 * `parse()` owns the orchestration every bank parser used to duplicate:
39	 * strip BOM → `parseCSV` → empty-file guard → resolve the column layout →
40	 * loop the data rows → collect transactions and errors, all wrapped in a single
41	 * `try/catch`. Subclasses supply only what varies via two hooks:
42	 * `resolveLayout()` (header detection + column matching) and `parseRow()` (how a
43	 * single row maps to a `ParsedTransaction`). See RF-01 in the refactoring backlog.
44	 */
45	export abstract class BaseCSVParser<TLayout extends CSVLayout = CSVLayout> implements ICSVParser {
46		/**
47		 * Minimum number of rows required before parsing is attempted. Most banks ship
48		 * a header row plus data (2). TD Bank has no header row (1). Wealth Simple
49		 * treats a header-only file as an empty-but-valid result, so it disables the
50		 * guard (0).
51		 */
52		protected minimumRowCount = 2;
53	
54		/**
55		 * Template Method: the single, shared parse pipeline for every bank parser.
56		 */
57		parse(csvContent: string): CSVParseResult {
58			const transactions: ParsedTransaction[] = [];
59			const errors: string[] = [];
60	
61			try {
62				const rows = this.parseCSV(this.removeBOM(csvContent));
63	
64				if (rows.length < this.minimumRowCount) {
65					errors.push('CSV file is empty or has no data rows');
66					return { transactions, errors };
67				}
68	
69				// Hook: locate the header / column indices. On failure the subclass
70				// pushes its own format error and returns null.
71				const layout = this.resolveLayout(rows, errors, csvContent);
72				if (!layout) {
73					return { transactions, errors };
74				}
75	
76				// Hook: map each data row to a transaction (or null to skip / on error).
77				for (let i = layout.dataStartIndex; i < rows.length; i++) {
78					const transaction = this.parseRow(rows[i], layout, i, errors);
79					if (transaction) {
80						transactions.push(transaction);
81					}
82				}
83			} catch (e: unknown) {
84				errors.push(`Failed to parse CSV: ${e instanceof Error ? e.message : 'Unknown error'}`);
85			}
86	
87			return { transactions, errors };
88		}
89	
90		abstract validateFormat(csvContent: string): boolean;
91	
92		/**
93		 * Hook: detect the header and resolve the column indices this parser needs.
94		 *
95		 * Return the layout on success, or `null` after pushing a format/column error
96		 * onto `errors`. The original (pre-BOM-strip) `csvContent` is provided for
97		 * parsers whose `validateFormat` re-parses the raw string.
98		 */
99		protected abstract resolveLayout(
100			rows: string[][],
101			errors: string[],
102			csvContent: string
103		): TLayout | null;
104	
105		/**
106		 * Hook: map a single data row to a transaction.
107		 *
108		 * Return `null` to skip the row silently (incomplete/empty) or after pushing a
109		 * per-row error. `rowIndex` is 0-based; user-facing messages use `rowIndex + 1`.
110		 */
111		protected abstract parseRow(
112			row: string[],
113			layout: TLayout,
114			rowIndex: number,
115			errors: string[]
116		): ParsedTransaction | null;
117	
118		/**
119		 * Shared row finaliser for parsers whose amount lives in a single value.
120		 *
121		 * Validates the vendor name, applies the per-bank sign convention via
122		 * `normalizeAmount`, and returns the finished transaction. Consolidating the
123		 * `normalizeAmount` → assignment step here is what lets `amount` land as a
124		 * plain `number` (RF-01): callers have already rejected a null raw amount, and
125		 * the guard below narrows `normalizeAmount`'s `number | null` result.
126		 *
127		 * @param rawAmount - Parsed, non-null amount (caller reports invalid amounts).
128		 * @param invertSign - Per-bank sign convention passed to `normalizeAmount`.
129		 */
130		protected finalizeRow(
131			transactionDate: string,
132			vendorName: string,
133			rawAmount: number,
134			invertSign: boolean,
135			rowNumber: number,
136			errors: string[],
137			missingVendorMessage = 'Missing vendor name/description'
138		): ParsedTransaction | null {
139			if (!vendorName) {
140				errors.push(`Row ${rowNumber}: ${missingVendorMessage}`);
141				return null;
142			}
143	
144			const amount = this.normalizeAmount(rawAmount, invertSign);
145			if (amount === null) return null;
146	
147			return { transaction_date: transactionDate, vendor_name: vendorName, amount };
148		}
149	
150		/**
151		 * Parse CSV string into rows and columns
152		 * Handles quoted fields with commas
153		 */
154		protected parseCSV(csvContent: string): string[][] {
155			const lines = csvContent.split(/\r?\n/);
156			const result: string[][] = [];
157	
158			// Strip a surviving surrounding "..." pair from a finalized field.
159			// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
160			// standard unwrap above reduces to `"-$33.00"` (literal " still present).
161			const stripOuterQuotes = (field: string): string => {
162				const trimmed = field.trim();
163				if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
164					return trimmed.slice(1, -1).trim();
165				}
166				return trimmed;
167			};
168	
169			for (const line of lines) {
170				if (!line.trim()) continue;
171	
172				const row: string[] = [];
173				let currentField = '';
174				let inQuotes = false;
175	
176				for (let i = 0; i < line.length; i++) {
177					const char = line[i];
178	
179					if (char === '"') {
180						// Handle escaped quotes
181						if (inQuotes && line[i + 1] === '"') {
182							currentField += '"';
183							i++; // Skip next quote
184						} else {
185							inQuotes = !inQuotes;
186						}
187					} else if (char === ',' && !inQuotes) {
188						row.push(stripOuterQuotes(currentField));
189						currentField = '';
190					} else {
191						currentField += char;
192					}
193				}
194	
195				// Add the last field
196				row.push(stripOuterQuotes(currentField));
197				result.push(row);
198			}
199	
200			return result;
201		}
202	
203		/**
204		 * Parse a date string in MM/DD/YYYY or YYYY-MM-DD format to YYYY-MM-DD
205		 */
206		protected parseDate(dateStr: string): string | null {
207			try {
208				// Remove any leading/trailing whitespace
209				dateStr = dateStr.trim();
210	
211				// Try YYYY-MM-DD format (new EQ Bank format)
212				const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
213				if (ymdMatch) {
214					const [, year, month, day] = ymdMatch;
215					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
216				}
217	
218				// Try MM/DD/YYYY format
219				const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
220				if (mdyMatch) {
221					const [, month, day, year] = mdyMatch;
222					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
223				}
224	
225				// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
226				const dmmyMatch = dateStr.match(/^(\d{1,2})[\s-]([A-Za-z]{3})[.\s-]*(\d{2,4})$/);
227				if (dmmyMatch) {
228					const [, day, monthStr, year] = dmmyMatch;
229					const monthMap: Record<string, string> = {
230						jan: '01',
231						feb: '02',
232						mar: '03',
233						apr: '04',
234						may: '05',
235						jun: '06',
236						jul: '07',
237						aug: '08',
238						sep: '09',
239						oct: '10',
240						nov: '11',
241						dec: '12'
242					};
243					const month = monthMap[monthStr.toLowerCase()];
244					if (month) {
245						const fullYear = year.length === 2 ? `20${year}` : year;
246						return `${fullYear}-${month}-${day.padStart(2, '0')}`;
247					}
248				}
249	
250				// Try DD Mon YYYY format with full month name
251				const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
252				if (dmonyMatch) {
253					const [, day, monthStr, year] = dmonyMatch;
254					const monthMap: Record<string, string> = {
255						january: '01',
256						february: '02',
257						march: '03',
258						april: '04',
259						may: '05',
260						june: '06',
261						july: '07',
262						august: '08',
263						september: '09',
264						october: '10',
265						november: '11',
266						december: '12'
267					};
268					const month = monthMap[monthStr.toLowerCase()];
269					if (month) {
270						return `${year}-${month}-${day.padStart(2, '0')}`;
271					}
272				}
273	
274				return null;
275			} catch {
276				return null;
277			}
278		}
279	
280		/**
281		 * Parse amount from string, handling currency symbols, commas, and parentheses for negatives
282		 */
283		protected parseAmount(amountStr: string): number | null {
284			try {
285				// Trim whitespace and any surrounding quote characters left over from
286				// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
287				// unwraps once to a value still containing literal " characters).
288				amountStr = amountStr
289					.trim()
290					.replace(/^["']+|["']+$/g, '')
291					.trim();
292	
293				// Check if amount is in parentheses (negative)
294				const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
295				if (isNegative) {
296					amountStr = amountStr.slice(1, -1);
297				}
298	
299				// Remove currency symbols, commas, whitespace, and any embedded quotes
300				amountStr = amountStr.replace(/[$,\s"']/g, '');
301	
302				// Parse the number
303				const amount = parseFloat(amountStr);
304				if (isNaN(amount)) return null;
305	
306				return isNegative ? -Math.abs(amount) : amount;
307			} catch {
308				return null;
309			}
310		}
311	
312		/**
313		 * Remove BOM (Byte Order Mark) if present
314		 */
315		protected removeBOM(content: string): string {
316			if (content.charCodeAt(0) === 0xfeff) {
317				return content.slice(1);
318			}
319			return content;
320		}
321	
322		/**
323		 * Check if a header row contains expected columns (case-insensitive)
324		 */
325		protected hasExpectedColumns(header: string[], expectedColumns: string[]): boolean {
326			const headerLower = header.map((h) => h.toLowerCase().trim());
327			return expectedColumns.every((col) => headerLower.includes(col.toLowerCase()));
328		}
329	
330		/**
331		 * Normalizes transaction amounts to positive values for expenses.
332		 *
333		 * For user-friendly display, expenses should be positive and refunds/credits should be negative.
334		 * Different banks use different conventions:
335		 * - PC Financial, EQ Bank, RBC, TD Bank, Simplii, Wealth Simple: Use negative for expenses → Need inversion
336		 * - American Express: Already uses positive for expenses → No inversion needed
337		 *
338		 * @param amount - The parsed amount from CSV
339		 * @param invertSign - If true, inverts the sign (for banks using negative for expenses). Default: true
340		 * @returns Normalized amount (positive = expense, negative = refund/credit) or null if input is null
341		 *
342		 * @example
343		 * // PC Financial: -50.00 (expense) → keep as-is
344		 * normalizeAmount(-50.00, false) // Returns -50.00
345		 *
346		 * @example
347		 * // American Express: 50.00 (expense) → invert to -50.00
348		 * normalizeAmount(50.00, true) // Returns -50.00
349		 *
350		 * @example
351		 * // PC Financial: 25.00 (refund) → keep as-is
352		 * normalizeAmount(25.00, false) // Returns 25.00
353		 *
354		 * Specification: #{#trn1b}
355		 */
356		protected normalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
357			if (amount === null || amount === undefined) return null;
358			if (amount === 0) return 0;
359	
360			return invertSign ? amount * -1 : amount;
361		}
362	}
