5	// Test implementation of BaseCSVParser for testing protected methods. It inherits
6	// the shared `parse()` Template Method and supplies no-op layout/row hooks, since
7	// these tests only exercise the protected `normalizeAmount` utility.
8	class TestCSVParser extends BaseCSVParser {
9		validateFormat(): boolean {
10			return true;
11		}
12	
13		protected resolveLayout(): CSVLayout | null {
14			return { dataStartIndex: 0 };
15		}
16	
17		protected parseRow(): null {
18			return null;
19		}
20	
21		// Expose protected methods for testing
22		public testNormalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
23			return this.normalizeAmount(amount, invertSign);
24		}
25	}
