27	describe('BaseCSVParser', () => {
28		const parser = new TestCSVParser();
29	
30		describe('normalizeAmount - #{#trn1b}', () => {
31			describe('when invertSign is true (for banks like Amex where positive = expense in CSV)', () => {
32				it('should convert positive expense to negative', () => {
33					// American Express: 50.00 (expense in CSV) → -50.00 (negative = expense)
34					expect(parser.testNormalizeAmount(-50.0, true)).toBe(50.0);
35				});
36	
37				it('should convert negative refund to positive', () => {
