39					expect(parser.testNormalizeAmount(25.0, true)).toBe(-25.0);
40				});
41	
42				it('should handle large negative amounts', () => {
43					expect(parser.testNormalizeAmount(-1234.56, true)).toBe(1234.56);
44				});
45	
46				it('should handle large positive amounts', () => {
47					expect(parser.testNormalizeAmount(9999.99, true)).toBe(-9999.99);
48				});
49	
50				it('should handle amounts with many decimals', () => {
51					expect(parser.testNormalizeAmount(-123.456789, true)).toBe(123.456789);
52				});
53			});
54	
