56				it('should keep negative expense as negative', () => {
57					// PC Financial: -50.00 (expense) → -50.00 (negative = expense)
58					expect(parser.testNormalizeAmount(50.0, false)).toBe(50.0);
59				});
60	
61				it('should keep positive refund as positive', () => {
62					// PC Financial: 25.00 (refund) → 25.00 (positive = refund)
63					expect(parser.testNormalizeAmount(-25.0, false)).toBe(-25.0);
64				});
65	
