import { describe, it, expect } from 'vitest';
import { BaseCSVParser } from '../BaseCSVParser';
import type { CSVLayout } from '../BaseCSVParser';

// Test implementation of BaseCSVParser for testing protected methods. It inherits
// the shared `parse()` Template Method and supplies no-op layout/row hooks, since
// these tests only exercise the protected `normalizeAmount` utility.
//
// Uses the default sign convention (`expensesArePositive = false`): the bank
// already exports expenses as negative, so amounts pass through unchanged.
class TestCSVParser extends BaseCSVParser {
	validateFormat(): boolean {
		return true;
	}

	protected resolveLayout(): CSVLayout | null {
		return { dataStartIndex: 0 };
	}

	protected parseRow(): null {
		return null;
	}

	// Expose protected method for testing
	public testNormalizeAmount(amount: number | null): number | null {
		return this.normalizeAmount(amount);
	}
}

// Amex-style sign convention: the bank exports expenses as positive, so
// `normalizeAmount` inverts the sign to the app convention (negative = expense).
class InvertingTestCSVParser extends TestCSVParser {
	protected override readonly expensesArePositive = true;
}

describe('BaseCSVParser', () => {
	const parser = new TestCSVParser();
	const invertingParser = new InvertingTestCSVParser();

	describe('normalizeAmount - #{#trn1b}', () => {
		describe('when expensesArePositive is true (banks like Amex where positive = expense in CSV)', () => {
			it('should convert positive expense to negative', () => {
				// American Express: 50.00 (expense in CSV) → -50.00 (negative = expense)
				expect(invertingParser.testNormalizeAmount(-50.0)).toBe(50.0);
			});

			it('should convert negative refund to positive', () => {
				// American Express: -25.00 (refund in CSV) → 25.00 (positive = refund)
				expect(invertingParser.testNormalizeAmount(25.0)).toBe(-25.0);
			});

			it('should handle large negative amounts', () => {
				expect(invertingParser.testNormalizeAmount(-1234.56)).toBe(1234.56);
			});

			it('should handle large positive amounts', () => {
				expect(invertingParser.testNormalizeAmount(9999.99)).toBe(-9999.99);
			});

			it('should handle amounts with many decimals', () => {
				expect(invertingParser.testNormalizeAmount(-123.456789)).toBe(123.456789);
			});
		});

		describe('when expensesArePositive is false (banks already using negative for expenses)', () => {
			it('should keep negative expense as negative', () => {
				// PC Financial: -50.00 (expense) → -50.00 (negative = expense)
				expect(parser.testNormalizeAmount(50.0)).toBe(50.0);
			});

			it('should keep positive refund as positive', () => {
				// PC Financial: 25.00 (refund) → 25.00 (positive = refund)
				expect(parser.testNormalizeAmount(-25.0)).toBe(-25.0);
			});

			it('should handle large amounts unchanged', () => {
				expect(parser.testNormalizeAmount(5000.0)).toBe(5000.0);
				expect(parser.testNormalizeAmount(-5000.0)).toBe(-5000.0);
			});
		});

		describe('edge cases', () => {
			it('should handle null amount', () => {
				expect(invertingParser.testNormalizeAmount(null)).toBeNull();
				expect(parser.testNormalizeAmount(null)).toBeNull();
			});

			it('should handle zero amount with expensesArePositive true', () => {
				expect(invertingParser.testNormalizeAmount(0)).toBe(0);
			});

			it('should handle zero amount with expensesArePositive false', () => {
				expect(parser.testNormalizeAmount(0)).toBe(0);
			});

			it('should handle negative zero', () => {
				expect(invertingParser.testNormalizeAmount(-0)).toBe(0);
				expect(parser.testNormalizeAmount(-0)).toBe(0);
			});

			it('should handle very small amounts', () => {
				expect(invertingParser.testNormalizeAmount(-0.01)).toBe(0.01);
				expect(invertingParser.testNormalizeAmount(0.01)).toBe(-0.01);
			});

			it('should handle very large amounts', () => {
				expect(invertingParser.testNormalizeAmount(-999999.99)).toBe(999999.99);
				expect(parser.testNormalizeAmount(999999.99)).toBe(999999.99);
			});
		});

		describe('default sign convention', () => {
			it('should default expensesArePositive to false (keep signs as-is)', () => {
				// Base default: bank already uses negative for expenses → no inversion
				expect(parser.testNormalizeAmount(-50.0)).toBe(-50.0);
				expect(parser.testNormalizeAmount(25.0)).toBe(25.0);
			});
		});
	});
});
